<?php
defined('ABSPATH') || exit;

(static function () use ($attributes) {

if (!function_exists('wc_get_product')) return;
require_once dirname(__DIR__) . '/helpers.php';

$wrapper = get_block_wrapper_attributes(['class' => 'coursetransit-block coursetransit-dashboard']);
// phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- Generated by get_block_wrapper_attributes(), which escapes attribute values.
echo '<div ' . $wrapper . '>';

if (!is_user_logged_in()) {
    $login_url = function_exists('wc_get_page_permalink') ? wc_get_page_permalink('myaccount') : wp_login_url();
    echo '<div class="coursetransit-block-notice"><p>' . esc_html__('Please log in to access your dashboard.', 'coursetransit') . '</p>';
    echo '<a class="wp-element-button" href="' . esc_url($login_url) . '">' . esc_html__('Log In', 'coursetransit') . '</a></div></div>';
    return;
}

$user = wp_get_current_user();
$enrollment_map = coursetransit_blocks_get_enrolled_product_data($user->ID);
$product_ids = array_keys($enrollment_map);
$courses = coursetransit_blocks_get_course_products($product_ids, 50, $enrollment_map);

$progress_items = [];
foreach ($courses as $course) {
    $progress_items[] = [
        'course' => $course,
        'progress' => coursetransit_blocks_get_course_progress($course, $user->ID),
    ];
}
$completed = count(array_filter($progress_items, static function ($item) { return $item['progress']['status'] === 'completed'; }));
$in_progress = count(array_filter($progress_items, static function ($item) { return $item['progress']['status'] === 'in-progress'; }));
$not_started = count(array_filter($progress_items, static function ($item) { return $item['progress']['status'] === 'not-started'; }));
$overall = $progress_items ? (int) round(array_sum(array_map(static function ($item) { return $item['progress']['percent']; }, $progress_items)) / count($progress_items)) : 0;

if (!empty($attributes['showWelcome'])) {
    echo '<section class="coursetransit-dashboard__welcome">';
    echo '<div><h2 class="wp-block-heading">' . sprintf(
        /* translators: %s: the logged-in learner's display name. */
        esc_html__('Welcome, %s', 'coursetransit'),
        esc_html($user->display_name ?: $user->user_login)
    ) . '</h2>';
    echo '<p>' . esc_html__('Continue learning from your enrolled courses and keep track of your progress.', 'coursetransit') . '</p></div>';
    echo '</section>';
}

if (!empty($attributes['showStats'])) {
    echo '<section class="coursetransit-dashboard__stats">';
    foreach ([
        [$completed, __('Completed', 'coursetransit')],
        [$in_progress, __('In Progress', 'coursetransit')],
        [$not_started, __('Not Started', 'coursetransit')],
        [$overall . '%', __('Overall Progress', 'coursetransit')],
    ] as $stat) {
        echo '<div class="coursetransit-dashboard__stat"><span class="coursetransit-dashboard__stat-value">' . esc_html($stat[0]) . '</span><span class="coursetransit-dashboard__stat-label">' . esc_html($stat[1]) . '</span></div>';
    }
    echo '</section>';
}

if (!empty($attributes['showActions'])) {
    $account_url = function_exists('wc_get_page_permalink') ? wc_get_page_permalink('myaccount') : home_url('/');
    $courses_url = function_exists('wc_get_page_permalink') ? wc_get_page_permalink('shop') : home_url('/');
    echo '<div class="coursetransit-dashboard__actions">';
    echo '<div class="wp-block-button"><a class="wp-block-button__link wp-element-button coursetransit-dashboard__button" href="' . esc_url($account_url) . '">' . esc_html__('My Account', 'coursetransit') . '</a></div>';
    echo '<div class="wp-block-button"><a class="wp-block-button__link wp-element-button coursetransit-dashboard__button" href="' . esc_url($courses_url) . '">' . esc_html__('Browse Courses', 'coursetransit') . '</a></div>';
    echo '</div>';
}

if (!empty($attributes['showRecentCourses'])) {
    usort($progress_items, static function ($a, $b) use ($enrollment_map) {
        $a_id = absint($a['course']['wc_product_id'] ?? 0);
        $b_id = absint($b['course']['wc_product_id'] ?? 0);
        return ((int) ($enrollment_map[$b_id] ?? 0)) <=> ((int) ($enrollment_map[$a_id] ?? 0));
    });
    // Keep the dashboard self-contained: expand additional enrolled courses inline.
    $visible_items = array_slice($progress_items, 0, 3);
    $additional_items = array_slice($progress_items, 3);
    $render_course_items = static function ($items) use ($user) {
        if (!$items) {
            return;
        }
        echo '<div class="coursetransit-dashboard__course-list">';
        foreach ($items as $item) {
            $course = $item['course'];
            $url = coursetransit_blocks_moodle_course_url($course);
            if (!$url) {
                continue;
            }
            echo '<article class="coursetransit-dashboard__course">';
            echo '<div class="coursetransit-dashboard__course-main"><h4><a href="' . esc_url($url) . '">' . esc_html($course['fullname']) . '</a></h4>';
            coursetransit_blocks_render_progress($course, $user->ID, true);
            echo '</div>';
            echo '<div class="wp-block-button coursetransit-dashboard__continue-wrap"><a class="wp-block-button__link wp-element-button coursetransit-dashboard__continue" href="' . esc_url($url) . '">' . esc_html__('Continue', 'coursetransit') . '</a></div>';
            echo '</article>';
        }
        echo '</div>';
    };
    echo '<section class="coursetransit-dashboard__recent">';
    echo '<div class="coursetransit-dashboard__section-header"><h3 class="wp-block-heading">' . esc_html__('Continue Learning', 'coursetransit') . '</h3></div>';
    if ($progress_items) {
        $render_course_items($visible_items);
        if ($additional_items) {
            echo '<details class="coursetransit-dashboard__all-courses">';
            echo '<summary>' . esc_html__('View all my courses', 'coursetransit') . '</summary>';
            $render_course_items($additional_items);
            echo '</details>';
        }
    } else {
        echo '<p>' . esc_html__('No enrolled courses found.', 'coursetransit') . '</p>';
    }
    echo '</section>';
}

echo '</div>';

})();
